#include <hexi.h>
#include <cstdint>
#include <string>
#include <vector>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;

    void serialise(auto& stream) {
        // Write packet_id
        stream & packet_id;

        // Write username with length prefix (default behavior for strings)
        stream & username;

        // Write scores vector with count prefix
        stream & hexi::prefixed(scores);

        // Write metadata as null-terminated string
        stream & hexi::null_terminated(metadata);
    }
};

std::vector<uint8_t> serialize_packet(const NetworkPacket& packet) {
    // Create a buffer to hold the serialized data
    std::vector<uint8_t> buffer;

    // Create a buffer adaptor for the vector
    hexi::buffer_adaptor adaptor(buffer);

    // Create a binary stream with the adaptor
    hexi::binary_stream stream(adaptor);

    // Serialize the packet using the stream
    stream.serialise(const_cast<NetworkPacket&>(packet));

    // Return the buffer containing the serialized data
    return buffer;
}
```

