#include <hexi.h>
#include <span>
#include <string>
#include <string_view>
#include <vector>
#include <cstdint>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;
};

NetworkPacket deserialize_packet(const std::span<const uint8_t> buffer) {
    // Create buffer adaptor and binary stream for reading
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    NetworkPacket packet;

    // Read the packet_id (4 bytes, uint32_t)
    stream >> packet.packet_id;

    // Read the username using the length prefix
    // The prefixed adaptor reads a 32-bit length prefix followed by the data
    stream >> hexi::prefixed(packet.username);

    // Read the scores vector using prefixed adaptor
    // This reads the count, then uses read_container to read the scores vector
    stream >> hexi::prefixed(packet.scores);

    // Read the metadata string as null-terminated for zero-copy
    stream >> hexi::null_terminated(packet.metadata);

    // Note: Any remaining padding bytes would be automatically skipped when the stream
    // goes out of scope, or we could explicitly skip them if needed
    // The stream tracks its position internally

    return packet;
}

struct PacketInfo {
    uint32_t packet_id;
    std::string_view username;
};

PacketInfo extract_packet_info(const std::span<const uint8_t> buffer) {
    // Create buffer adaptor and binary stream for reading
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    PacketInfo info;

    // Use span() to get a zero-copy view of the packet_id (first 4 bytes)
    auto packet_id_span = stream.span<uint32_t>(1);
    info.packet_id = packet_id_span[0];

    // Read username using prefixed adaptor to get a string_view
    // This provides a zero-copy view into the buffer
    stream >> hexi::prefixed(info.username);

    // Skip the scores vector without reading its elements
    // First, read the count (32-bit prefix used by the prefixed adaptor)
    uint32_t scores_count = 0;
    stream >> scores_count;

    // Then skip the data: count * sizeof(uint32_t) bytes
    stream.skip(scores_count * sizeof(uint32_t));

    // We've now extracted the packet_id and username without fully deserializing
    // the entire packet

