#include <hexi/hexi.h>
#include <span>
#include <string_view>
#include <cstdint>

struct PacketHeader {
    uint8_t version;
    uint8_t flags;
    uint16_t packet_id;
};

PacketHeader read_packet_header(const std::span<const uint8_t> buffer) {
    // Wrap the buffer with a Hexi buffer adaptor
    hexi::buffer_adaptor adaptor(buffer);

    // Create a binary stream for zero-copy operations
    hexi::binary_stream stream(adaptor);

    // Use span() to get a zero-copy view of the header structure
    // This returns a span pointing directly to the buffer data
    auto header_span = stream.span<PacketHeader>(1);

    // Return the first element (the header)
    // This is safe because span() enforces bounds checking
    if (stream.good() && !header_span.empty()) {
        return header_span[0];
    }

    // Return a default-initialized header if there was an error
    return PacketHeader{};
}

std::string_view read_message_until_delimiter(const std::span<const uint8_t> buffer) {
    // Wrap the buffer with a Hexi buffer adaptor
    hexi::buffer_adaptor adaptor(buffer);

    // Create a binary stream for zero-copy operations
    hexi::binary_stream stream(adaptor);

    // Use view() to read a null-terminated string with zero-copy
    // This returns a string_view pointing directly to the buffer data
    // The default terminator is '\0' (null byte)
    return stream.view();
}
```

This implementation uses the Hexi library's zero-copy features:

1. **`read_packet_header`**: Uses `span<PacketHeader>(1)` to create a zero-copy view of exactly one `PacketHeader` structure from the buffer. The data is not copied - the span points directly to the buffer's memory.

