   381→	/**
   382→	 * @brief Read data from the stream to the destination represented by the iterators.
   383→	 * 
   384→	 * @param[out] begin The beginning iterator.
   385→	 * @param end The end iterator.
   386→	 */
   387→	template<typename It>
   388→	void get(It begin, const It end) {
   389→		for(; begin != end; ++begin) {
   390→			*this >> *begin;
   391→		}
   392→	}
   393→
   394→	/**
   395→	 * @brief Read data from the stream into the provided destination argument.
   396→	 * 
   397→	 * @param[out] dest A contiguous range into which the data should be read.
   398→	 */
   399→	template<std::ranges::contiguous_range range>
   400→	void get(range& dest) {
   401→		const auto read_size = dest.size() * sizeof(typename range::value_type);
   402→		SAFE_READ(dest.data(), read_size, void());
   403→	}
