std::vector<uint8_t> read_buffer_data(const std::vector<uint8_t>& source_buffer, size_t bytes_to_read) {
    // Create a mutable copy of the source buffer to pass to buffer_adaptor
    // (buffer_adaptor requires a non-const reference)
    std::vector<uint8_t> buffer_copy = source_buffer;

    // Create buffer_adaptor to manage reading
    hexi::buffer_adaptor adaptor(buffer_copy);

    // Prepare destination buffer to hold the data
    std::vector<uint8_t> destination(bytes_to_read);

    // Read the specified number of bytes from the buffer
    adaptor.read(destination.data(), bytes_to_read);

    return destination;
}

void write_buffer_data(std::vector<uint8_t>& dest_buffer, const std::vector<uint8_t>& source_data) {
    // Create buffer_adaptor for the destination buffer
    hexi::buffer_adaptor adaptor(dest_buffer);

    // Write the source data to the destination buffer
    adaptor.write(source_data.data(), source_data.size());
}
```

