		  read_(0),
		  write_(0) {}

	buffer_adaptor(buffer_adaptor&& rhs) = delete;
	buffer_adaptor& operator=(buffer_adaptor&&) = delete;
	buffer_adaptor& operator=(const buffer_adaptor&) = delete;
	buffer_adaptor(const buffer_adaptor&) = delete;

