    // Need to cast away const since buffer_adaptor requires non-const reference
    // but we won't modify it since we're only using copy()
    std::vector<uint8_t>& non_const_buffer = const_cast<std::vector<uint8_t>&>(buffer);
    hexi::buffer_adaptor adaptor(non_const_buffer);

    // Create destination vector to hold the peeked data
    std::vector<uint8_t> peeked_data(bytes_to_peek);

    // Use copy() to peek at data without advancing the read pointer
    adaptor.copy(peeked_data.data(), bytes_to_peek);

    return peeked_data;
}
