    23→template<byte_type storage_type, std::size_t buf_size>
    24→class static_buffer final {
    25→	std::array<storage_type, buf_size> buffer_ = {};
    26→	std::size_t read_ = 0;
    27→	std::size_t write_ = 0;
    28→
    29→public:
    30→	using size_type       = typename decltype(buffer_)::size_type;
    31→	using offset_type     = size_type;
    32→	using value_type      = storage_type;
    33→	using contiguous      = is_contiguous;
    34→	using seeking         = supported;
