   251→	/**
   252→	 * @brief Determine whether the adaptor supports write seeking.
   253→	 * 
   254→	 * This is determined at compile-time and does not need to checked at
   255→	 * run-time.
   256→	 * 
   257→	 * @return True if write seeking is supported, otherwise false.
   258→	 */
   259→	constexpr static bool can_write_seek() {
   260→		return std::is_same_v<seeking, supported>;
   261→	}
   262→
   263→	/**
   264→	 * @brief Performs write seeking within the container.
   265→	 * 
   266→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   267→	 * @param offset The offset relative to the seek direction or the absolute value
   268→	 * when using absolute seeking.
   269→	 */
   270→	void write_seek(const buffer_seek direction, const offset_type offset) {
   271→		switch(direction) {
   272→			case buffer_seek::sk_backward:
   273→				write_ -= offset;
   274→				break;
   275→			case buffer_seek::sk_forward:
   276→				write_ += offset;
   277→				break;
   278→			case buffer_seek::sk_absolute:
   279→				write_ = offset;
   280→		}
   281→	}
   282→
   283→	/**
   284→	 * @return Pointer to the data available for reading.
   285→	 */
   286→	auto read_ptr() const {
   287→		return buffer_.data() + read_;
   288→	}
   289→
   290→	/**
   291→	 * @return Pointer to the data available for reading.
   292→	 */
   293→	auto read_ptr() {
   294→		return buffer_.data() + read_;
   295→	}
   296→
   297→	/**
   298→	 * @return Pointer to the location within the buffer where the next write
   299→	 * will be made.
   300→	 */
   301→	auto write_ptr() const {
   302→		return buffer_.data() + write_;
   303→	}
   304→
   305→	/**
   306→	 * @return Pointer to the location within the buffer where the next write
   307→	 * will be made.
   308→	 */
   309→	auto write_ptr() {
   310→		return buffer_.data() + write_;
   311→	}
   312→
   313→	/**
   314→	 * @return Pointer to the data available for reading.
   315→	 */
   316→	auto data() const {
   317→		return buffer_.data() + read_;
   318→	}
   319→
   320→	/**
   321→	 * @return Pointer to the data available for reading.
   322→	 */
   323→	auto data() {
   324→		return buffer_.data() + read_;
   325→	}
   326→
   327→	/**
   328→	 * @return Pointer to the underlying storage.
   329→	 */
   330→	auto storage() const {
   331→		return buffer_.data();
   332→	}
   333→
   334→	/**
   335→	 * @return Pointer to the underlying storage.
   336→	 */
   337→	auto storage() {
   338→		return buffer_.data();
   339→	}
   340→
   341→	/**
   342→	 * @brief Advances the write cursor.
   343→	 * 
   344→	 * @param size The number of bytes by which to advance the write cursor.
   345→	 */
   346→	void advance_write(size_type bytes) {
   347→		assert(buffer_.size() >= (write_ + bytes));
   348→		write_ += bytes;
   349→	}
   350→
   351→	/**
   352→	 * @brief The amount of space left in the container.
   353→	 * 
   354→	 * @return The number of free bytes.
   355→	 */
   356→	auto free() const {
   357→		return buffer_.size() - write_;
   358→	}
   359→	
   360→	/*
   361→	 * @brief Resets both the read and write cursors back to the beginning
   362→	 * of the buffer.
   363→	 * 
   364→	 * @note The underlying buffer will not be cleared but should be treated
   365→	 * as thought it has been.
   366→	 */
   367→	void clear() {
   368→		read_ = write_ = 0;
   369→	}
   370→};
