#include <hexi/hexi.h>
#include <span>
#include <vector>
#include <cstdint>

struct DataResult {
    uint8_t data_type;
    std::vector<uint32_t> int_items;
    std::vector<float> float_items;
};

DataResult preview_and_read_data(const std::span<const uint8_t> buffer) {
    DataResult result{};

    // Create a mutable copy of the buffer since buffer_adaptor requires non-const
    std::vector<uint8_t> buffer_copy(buffer.begin(), buffer.end());

    // Create buffer_adaptor to wrap the buffer
    hexi::buffer_adaptor adaptor(buffer_copy);

    // Preview the first byte (data_type) without advancing the read pointer
    uint8_t data_type = 0;
    adaptor.copy(&data_type, sizeof(data_type));
    result.data_type = data_type;

    // Check available data size - we need at least 1 byte (type) + 4 bytes (count)
    if (adaptor.size() < sizeof(uint8_t) + sizeof(uint32_t)) {
        return result; // Not enough data, return empty result
    }

    // Create binary_stream on top of the buffer_adaptor for structured reading
    hexi::binary_stream stream(adaptor);

    // Read the data_type (this time consuming it)
    stream >> result.data_type;

    // Read the item_count (uint32_t)
    uint32_t item_count = 0;
    stream >> item_count;

    // Check if we have enough data for the items
    const size_t item_size = (data_type == 0) ? sizeof(uint32_t) : sizeof(float);
    if (stream.size() < item_count * item_size) {
        return result; // Not enough data for all items
    }

    // Read the items based on the data type
    if (data_type == 0) {
        // Read integers
        result.int_items.reserve(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            uint32_t value = 0;
            stream >> value;
            result.int_items.push_back(value);
        }
    } else if (data_type == 1) {
        // Read floats
        result.float_items.reserve(item_count);
        for (uint32_t i = 0; i < item_count; ++i) {
            float value = 0.0f;
            stream >> value;
            result.float_items.push_back(value);
        }
    }

    return result;
}

