   341→	/**
   342→	 * @brief Advances the write cursor.
   343→	 * 
   344→	 * @param size The number of bytes by which to advance the write cursor.
   345→	 */
   346→	void advance_write(size_type bytes) {
   347→		assert(buffer_.size() >= (write_ + bytes));
   348→		write_ += bytes;
