    30→#define STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)            \
    31→	if(state_ != stream_state::ok) [[unlikely]] {                 \
    32→		return ret_var;                                           \
    33→	}                                                             \
    34→                                                                  \
    35→	enforce_read_bounds(read_size);                               \
    36→	                                                              \
    37→	if constexpr(std::is_same_v<exceptions, no_throw_t>) {        \
    38→		if(state_ != stream_state::ok) [[unlikely]] {             \
    39→			return ret_var;                                       \
    40→		}                                                         \
    41→	}
    42→
    43→#define SAFE_READ(dest, read_size, ret_var)                       \
    44→	STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)                \
    45→	buffer_.read(dest, read_size);
    46→
    47→template<
    48→	byte_oriented buf_type,
    49→	std::derived_from<except_tag> exceptions = HEXI_EXCEPTION_TAG,
    50→	std::derived_from<endian::storage_tag> endianness = endian::as_native_t
    51→>
    52→class binary_stream final {
    53→public:
    54→	using size_type          = typename buf_type::size_type;
    55→	using offset_type        = typename buf_type::offset_type;
    56→	using seeking            = typename buf_type::seeking;
    57→	using value_type         = typename buf_type::value_type;
    58→	using contiguous_type    = typename buf_type::contiguous;
    59→	
    60→	static constexpr endianness byte_order{};
    61→
    62→private:
    63→	using cond_size_type = std::conditional_t<writeable<buf_type>, size_type, std::monostate>;
    64→
    65→	buf_type& buffer_;
    66→	[[no_unique_address]] cond_size_type total_write_{};
    67→	size_type total_read_ = 0;
    68→	stream_state state_ = stream_state::ok;
    69→	const size_type read_limit_;
    70→
    71→	inline void enforce_read_bounds(const size_type read_size) {
    72→		if(read_size > buffer_.size()) [[unlikely]] {
    73→			state_ = stream_state::buff_limit_err;
    74→
    75→			if constexpr(std::is_same_v<exceptions, allow_throw_t>) {
    76→				HEXI_THROW(buffer_underrun(read_size, total_read_, buffer_.size()));
    77→			}
    78→
    79→			return;
    80→		}
    81→
    82→		if(read_limit_) {
    83→			const auto max_read_remaining = read_limit_ - total_read_;
    84→
    85→			if(read_size > max_read_remaining) [[unlikely]] {
    86→				state_ = stream_state::read_limit_err;
    87→
    88→				if constexpr(std::is_same_v<exceptions, allow_throw_t>) {
    89→					HEXI_THROW(stream_read_limit(read_size, total_read_, read_limit_));
    90→				}
    91→
    92→				return;
    93→			}
    94→		}
    95→
    96→		total_read_ += read_size;
    97→	}
    98→
    99→	template<typename T>
   100→	inline void advance_write(T&& arg) {
   101→		total_write_ += sizeof(T);
   102→	}
   103→
   104→	template<typename T, typename U>
   105→	inline void advance_write(T&&, U&& size) {
   106→		total_write_ += size;
   107→	}
   108→
   109→	template<typename... Ts>
   110→	inline void write(Ts&&... args) {
   111→		HEXI_TRY {
   112→			if(state_ == stream_state::ok) [[likely]] {
   113→				buffer_.write(std::forward<Ts>(args)...);
   114→				advance_write(std::forward<Ts>(args)...);                            
   115→			}
   116→		} HEXI_CATCH(...) {
   117→			state_ = stream_state::buff_write_err;
   118→
   119→			if constexpr(std::is_same_v<exceptions, allow_throw_t>) {
   120→				HEXI_THROW();
   121→			}
   122→		}
   123→	}
   124→
   125→	template<typename container_type>
   126→	void write_container(container_type& container) {
   127→		using cvalue_type = typename container_type::value_type;
   128→
   129→		if constexpr(memcpy_write<container_type, binary_stream>) {
   130→			const auto bytes = container.size() * sizeof(cvalue_type);
   131→			write(container.data(), static_cast<size_type>(bytes));
   132→		} else {
   133→			for(auto& element : container) {
   134→				*this << element;
   135→			}
   136→		}
   137→	}
   138→
   139→	template<typename container_type, typename count_type>
   140→	void read_container(container_type& container, const count_type count) {
   141→		using cvalue_type = typename container_type::value_type;
   142→
   143→		if constexpr(!memcpy_read<container_type, binary_stream>) {
   144→			container.clear();
   145→		}
   146→
   147→		if constexpr(has_reserve<container_type>) {
   148→			container.reserve(count);
   149→		}
   150→
   151→		if constexpr(memcpy_read<container_type, binary_stream>) {
   152→			container.resize(count);
   153→
   154→			const auto bytes = static_cast<size_type>(count * sizeof(cvalue_type));
   155→			SAFE_READ(container.data(), bytes, void());
   156→		} else {
   157→			for(count_type i = 0; i < count; ++i) {
   158→				cvalue_type value;
   159→				*this >> value;
   160→				container.emplace_back(std::move(value));
   161→			}
   162→		}
   163→	}
