void demonstrate_block_allocator_behavior() {
    std::cout << "=== Block Allocator Free List Demonstration ===" << std::endl;
    std::cout << "Element count: " << element_count << std::endl << std::endl;

    // Create a block allocator for integers with specified capacity
    hexi::block_allocator<int, element_count> allocator;

    std::cout << "1. Initial state after construction:" << std::endl;
    std::cout << "   - Free list is initialized with " << element_count << " blocks" << std::endl;
    std::cout << "   - Each block is linked (push() was called " << element_count << " times)" << std::endl;
    std::cout << "   - Head points to the last block added (LIFO structure)" << std::endl;
    std::cout << "   Active allocations: " << allocator.active_count << std::endl << std::endl;

    // Allocate some blocks - internally calls pop()
    std::cout << "2. Allocating 3 blocks (pop() called 3 times internally):" << std::endl;
    int* block1 = allocator.allocate(100);
    std::cout << "   Allocated block1 with value 100" << std::endl;
    std::cout << "   - pop() removed head from free list" << std::endl;
    std::cout << "   - head_ now points to next block in list" << std::endl;
    std::cout << "   Active: " << allocator.active_count 
              << ", Storage used: " << allocator.storage_active_count << std::endl;

    int* block2 = allocator.allocate(200);
    std::cout << "   Allocated block2 with value 200" << std::endl;
    std::cout << "   Active: " << allocator.active_count 
              << ", Storage used: " << allocator.storage_active_count << std::endl;

    int* block3 = allocator.allocate(300);
    std::cout << "   Allocated block3 with value 300" << std::endl;
    std::cout << "   Active: " << allocator.active_count 
              << ", Storage used: " << allocator.storage_active_count << std::endl;
    std::cout << "   Free blocks remaining in list: " << (element_count - 3) << std::endl << std::endl;

    // Deallocate a block - internally calls push()
    std::cout << "3. Deallocating block2 (push() called internally):" << std::endl;
    allocator.deallocate(block2);
    std::cout << "   - Block is returned to free list as new head" << std::endl;
    std::cout << "   - push() sets: block->next = head_, then head_ = block" << std::endl;
    std::cout << "   - LIFO: this block will be the next one allocated" << std::endl;
    std::cout << "   Active: " << allocator.active_count 
              << ", Storage used: " << allocator.storage_active_count << std::endl << std::endl;

    // Allocate again - should reuse the just-freed block
    std::cout << "4. Allocating new block (pop() reuses freed block):" << std::endl;
    int* block4 = allocator.allocate(400);
    std::cout << "   Allocated block4 with value 400" << std::endl;
    std::cout << "   - pop() returned the block we just freed (LIFO behavior)" << std::endl;
    std::cout << "   - Block address reused: " << (block4 == block2 ? "YES" : "NO") << std::endl;
    std::cout << "   Active: " << allocator.active_count 
              << ", Storage used: " << allocator.storage_active_count << std::endl << std::endl;

    // Test over-capacity allocation
    std::cout << "5. Testing over-capacity behavior:" << std::endl;
    int* blocks[element_count + 2];

    // Allocate remaining blocks from storage
    for (size_t i = 0; i < element_count - 2; ++i) {
        blocks[i] = allocator.allocate(static_cast<int>(i));
    }
    std::cout << "   Allocated " << (element_count - 2) << " more blocks from storage" << std::endl;
    std::cout << "   Storage used: " << allocator.storage_active_count 
              << ", Active: " << allocator.active_count << std::endl;

    // This will trigger fallback to new since free list is empty
    std::cout << "   Free list is now empty (pop() returns nullptr)" << std::endl;
    blocks[element_count - 2] = allocator.allocate(999);
    std::cout << "   Allocated beyond capacity - uses 'new' instead of storage" << std::endl;
    std::cout << "   Storage used: " << allocator.storage_active_count 
              << ", Heap allocations: " << allocator.new_active_count << std::endl << std::endl;

    // Demonstrate push() behavior on deallocation
    std::cout << "6. Free list management summary:" << std::endl;
    std::cout << "   push(block): Adds block to head of free list" << std::endl;
    std::cout << "     - block->next = head_" << std::endl;
    std::cout << "     - head_ = block" << std::endl;
    std::cout << "   pop(): Removes and returns head of free list" << std::endl;
    std::cout << "     - if (!head_) return nullptr" << std::endl;
    std::cout << "     - block = head_" << std::endl;
    std::cout << "     - head_ = block->next" << std::endl;
    std::cout << "     - return block" << std::endl << std::endl;

    std::cout << "7. Statistics:" << std::endl;
    std::cout << "   Total allocations: " << allocator.total_allocs << std::endl;
    std::cout << "   Total deallocations: " << allocator.total_deallocs << std::endl;
    std::cout << "   Currently active: " << allocator.active_count << std::endl;
    std::cout << "   From storage: " << allocator.storage_active_count << std::endl;
    std::cout << "   From heap: " << allocator.new_active_count << std::endl << std::endl;

    // Clean up remaining allocations
    std::cout << "8. Cleaning up (push() restores free list):" << std::endl;
    allocator.deallocate(block1);
    allocator.deallocate(block3);
    allocator.deallocate(block4);
    for (size_t i = 0; i < element_count - 1; ++i) {
        allocator.deallocate(blocks[i]);
    }

    std::cout << "   All blocks deallocated" << std::endl;
    std::cout << "   Active: " << allocator.active_count << std::endl;
    std::cout << "   Free list restored with " << (element_count) << " blocks" << std::endl;
    std::cout << "   (Each deallocation called push() to return block to free list)" << std::endl;

    std::cout << std::endl << "=== Demonstration Complete ===" << std::endl;
}
