    std::cout << "   Allocated block3 with value 300" << std::endl;
    std::cout << "   Active: " << allocator.active_count 
              << ", Storage used: " << allocator.storage_active_count << std::endl;
    std::cout << "   Free blocks remaining in list: " << (element_count - 3) << std::endl << std::endl;

