```cpp
#include <hexi/file_buffer.h>
#include <filesystem>
#include <vector>
#include <cstdint>

std::vector<uint8_t> preview_file_header(const std::filesystem::path& file_path, size_t header_size) {
    // Create a file buffer using the hexi library
    hexi::file_buffer buffer(file_path);

    // Check if file was opened successfully
    if (!buffer) {
        // Return empty vector if file couldn't be opened
        return std::vector<uint8_t>();
    }

    // Determine actual size to read (in case header_size is larger than file)
    size_t actual_size = std::min(header_size, buffer.size());

    // Create destination buffer for the header data
    std::vector<uint8_t> header(actual_size);

    // Use copy() method to preview data without advancing the read pointer
    // This allows inspecting the header before deciding to read the full file
    buffer.copy(header.data(), actual_size);

    // Check if copy operation succeeded
    if (!buffer) {
        // Return empty vector if an error occurred during copy
        return std::vector<uint8_t>();
    }

    // Return the header data
    return header;
}
```

