#include <hexi/file_buffer.h>
#include <filesystem>
#include <cstdint>

int32_t read_int32_from_file(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);

    if (!buffer) {
        throw std::runtime_error("Failed to open file: " + file_path.string());
    }

    int32_t value;
    buffer.read(&value);

    if (!buffer) {
        throw std::runtime_error("Failed to read int32_t from file: " + file_path.string());
    }

    return value;
}

float read_float_from_file(const std::filesystem::path& file_path) {
    hexi::file_buffer buffer(file_path);

    if (!buffer) {
        throw std::runtime_error("Failed to open file: " + file_path.string());
    }

    float value;
    buffer.read(&value);

    if (!buffer) {
        throw std::runtime_error("Failed to read float from file: " + file_path.string());
    }

    return value;
}
```

## Explanation

Both functions follow the same pattern:

1. **Create a `file_buffer` object**: Pass the `file_path` to the constructor to open the file
2. **Check for errors**: Use the `operator bool()` to verify the file was opened successfully
3. **Read the data**: Use the templated `read(T* destination)` method which automatically reads `sizeof(T)` bytes
4. **Verify the read**: Check again that no error occurred during the read operation
5. **Return the value**: Return the read value

The `file_buffer` class handles all the low-level file operations, positioning, and error checking internally. The `read` method advances the internal read cursor automatically, so subsequent reads would read the next value in the file.

