   102→public:
   103→	explicit binary_stream_reader(buffer_read& source, std::size_t read_limit = 0)
   104→		: stream_base(source),
   105→		  buffer_(source),
   106→		  total_read_(0),
   107→		  read_limit_(read_limit) {}
   108→
   109→	explicit binary_stream_reader(buffer_read& source, no_throw_t, std::size_t read_limit = 0)
   110→		: stream_base(source, false),
   111→		  buffer_(source),
   112→		  total_read_(0),
   113→		  read_limit_(read_limit) {}
   114→
   115→	binary_stream_reader(binary_stream_reader&& rhs) noexcept
   116→		: stream_base(rhs),
   117→		  buffer_(rhs.buffer_),
   118→		  total_read_(rhs.total_read_),
   119→		  read_limit_(rhs.read_limit_) {
