   139→
   140→	// read the integers back one by one, making sure they
   141→	// match the expected value
   142→	for(auto value : in) {
   143→		int output = -1;
   144→		stream >> output;
   145→		ASSERT_EQ(output, value);
   146→	}
   147→
   148→	stream.put(in.begin(), in.end());
   149→	std::vector<int> out(in.size());
