    25→#define STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)            \
    26→	if(state() != stream_state::ok) [[unlikely]] {                \
    27→		return ret_var;                                           \
    28→	}                                                             \
    29→                                                                  \
    30→	enforce_read_bounds(read_size);                               \
    31→	                                                              \
    32→	if(!allow_throw()) {                                          \
    33→		if(state() != stream_state::ok) [[unlikely]] {            \
    34→			return ret_var;                                       \
    35→		}                                                         \
    36→	}
    37→
    38→#define SAFE_READ(dest, read_size, ret_var)                       \
    39→	STREAM_READ_BOUNDS_ENFORCE(read_size, ret_var)                \
    40→	buffer_.read(dest, read_size);
    41→
    42→class binary_stream_reader : virtual public stream_base {
    43→	buffer_read& buffer_;
    44→	std::size_t total_read_;
    45→	const std::size_t read_limit_;
    46→
    47→	inline void enforce_read_bounds(const std::size_t read_size) {
    48→		if(read_size > buffer_.size()) [[unlikely]] {
    49→			set_state(stream_state::buff_limit_err);
    50→
    51→			if(allow_throw()) {
    52→				HEXI_THROW(buffer_underrun(read_size, total_read_, buffer_.size()));
    53→			}
    54→
    55→			return;
    56→		}
    57→
    58→		if(read_limit_) {
    59→			const auto max_read_remaining = read_limit_ - total_read_;
    60→
    61→			if(read_size > max_read_remaining) [[unlikely]] {
    62→				set_state(stream_state::read_limit_err);
    63→
    64→				if(allow_throw()) {
    65→					HEXI_THROW(stream_read_limit(read_size, total_read_, read_limit_));
    66→				}
    67→
    68→				return;
    69→			}
    70→		}
    71→
    72→		total_read_ += read_size;
    73→	}
    74→
    75→	template<typename container_type, typename count_type>
    76→	void read_container(container_type& container, const count_type count) {
    77→		using cvalue_type = typename container_type::value_type;
    78→
    79→		if constexpr(!memcpy_read<container_type, binary_stream_reader>) {
    80→			container.clear();
    81→		}
    82→
    83→		if constexpr(has_reserve<container_type>) {
    84→			container.reserve(count);
    85→		}
    86→
    87→		if constexpr(memcpy_read<container_type, binary_stream_reader>) {
    88→			container.resize(count);
    89→
    90→			const auto bytes = count * sizeof(cvalue_type);
    91→			SAFE_READ(container.data(), bytes, void());
    92→		} else {
    93→			for(count_type i = 0; i < count; ++i) {
    94→				cvalue_type value;
    95→				*this >> value;
    96→				container.emplace_back(std::move(value));
    97→			}
    98→		}
    99→	}

