    36→		return user_id == rhs.user_id
    37→			&& username == rhs.username
    38→			&& timestamp == rhs.timestamp
    39→			&& has_optional_field == rhs.has_optional_field
    40→			&& optional_field == rhs.optional_field;
    41→	}
    42→};
