    23→TEST(binary_stream_pmc, message_read_limit) {
    24→	std::array<std::uint8_t, 14> ping {
    25→		0x00, 0x0C, 0xDC, 0x01, 0x00, 0x00, 0x01,
    26→		0x00, 0x00, 0x00, 0xF4, 0x01, 0x00, 0x00
    27→	};
    28→
    29→	// write the ping packet data twice to the buffer
    30→	hexi::dynamic_buffer<32> buffer;
    31→	buffer.write(ping.data(), ping.size());
    32→	buffer.write(ping.data(), ping.size());
    33→
    34→	// read one packet back out (reuse the ping array)
    35→	hexi::pmc::binary_stream stream(buffer, ping.size());
    36→	ASSERT_EQ(stream.read_limit(), ping.size());
    37→	ASSERT_NO_THROW(stream.get(ping.data(), ping.size()))
    38→		<< "Failed to read packet back from stream";
    39→
    40→	// attempt to read past the stream message bound
    41→	ASSERT_THROW(stream.get(ping.data(), ping.size()), hexi::stream_read_limit)
    42→		<< "Message boundary was not respected";
    43→	ASSERT_EQ(stream.state(), hexi::stream_state::read_limit_err)
    44→		<< "Unexpected stream state";
    45→}
