   846→	 * @param count The number of bytes to be read.
   847→	 */
   848→	void get(std::string& dest, size_type size) {
   849→		STREAM_READ_BOUNDS_ENFORCE(size, void());
   850→
   851→		dest.resize_and_overwrite(size, [&](char* strbuf, size_type len) {
   852→			buffer_.read(strbuf, len);
   853→			return len;
   854→		});
   855→	}
   856→
   857→	/**
   858→	 * @brief Read data from the stream into the provided destination argument.
   859→	 * 
   860→	 * @param[out] dest The destination buffer.
   861→	 * @param count The number of elements to be read to the destination.
   862→	 */
   863→	template<typename T>
   864→	void get(T* dest, size_type count) {
   865→		assert(dest);
   866→		const auto read_size = count * sizeof(T);
   867→		SAFE_READ(dest, read_size, void());
   868→	}
   869→
   870→	/**
   871→	 * @brief Read data from the stream to the destination represented by the iterators.
   872→	 * 
   873→	 * @param[out] begin The beginning iterator.
   874→	 * @param end The end iterator.
   875→	 */
   876→	template<typename It>
   877→	void get(It begin, const It end) {
   878→		for(; begin != end; ++begin) {
   879→			*this >> *begin;
   880→		}
   881→	}
   882→
   883→	/**
   884→	 * @brief Read data from the stream into the provided destination argument.
   885→	 * 
   886→	 * @param[out] dest A contiguous range into which the data should be read.
   887→	 */
   888→	template<std::ranges::contiguous_range range>
   889→	void get(range& dest) {
   890→		const auto read_size = dest.size() * sizeof(typename range::value_type);
   891→		SAFE_READ(dest.data(), read_size, void());
   892→	}
   893→
   894→	/**
   895→	 * @brief Skip over a number of bytes.
   896→	 *
   897→	 * Skips over a number of bytes from the stream. This should be used
   898→	 * if the stream holds data that you don't care about but don't want
   899→	 * to have to read it to another buffer to access data beyond it.
   900→	 * 
   901→	 * @param length The number of bytes to skip.
   902→	 */
   903→	void skip(const size_type length) {
   904→		STREAM_READ_BOUNDS_ENFORCE(length, void());
   905→		buffer_.skip(length);
   906→	}
   907→
   908→	/**
   909→	 * @brief Provides a string_view over the stream's data, up to the terminator value.
   910→	 * 
   911→	 * @param terminator An optional terminating/sentinel value.
   912→	 * 
   913→	 * @return A string view over data up to the provided terminator.
   914→	 * An empty string_view if a terminator is not found
   915→	 */
   916→	std::string_view view(value_type terminator = value_type(0)) requires contiguous<buf_type> {
   917→		const auto pos = buffer_.find_first_of(terminator);
   918→
   919→		if(pos == buf_type::npos) {
   920→			return {};
   921→		}
   922→
   923→		std::string_view view { reinterpret_cast<char*>(buffer_.read_ptr()), pos };
   924→
   925→		// no need to enforce bounds, we know there's enough data
   926→		buffer_.skip(pos + 1);
   927→		total_read_ += (pos + 1);
   928→		return view;
   929→	}
   930→
   931→	/**
   932→	 * @brief Provides a span over the specified number of elements in the stream.
   933→	 * 
   934→	 * @param count The number of elements the span will provide a view over.
   935→	 * 
   936→	 * @return A span representing a view over the requested number of elements
   937→	 * in the stream.
   938→	 * 
   939→	 * @note The stream will error if the stream does not contain the requested amount of data.
   940→	 */
   941→	template<typename out_type = value_type>
   942→	std::span<out_type> span(size_type count) requires contiguous<buf_type> {
   943→		std::span view { reinterpret_cast<out_type*>(buffer_.read_ptr()), count };
   944→		skip(sizeof(out_type) * count);
   945→		return (state_ == stream_state::ok? view : std::span<out_type>());
   946→	}
   947→
   948→	/**  Misc functions **/
   949→
   950→	/**
   951→	 * @brief Determine whether the adaptor supports write seeking.
   952→	 * 
   953→	 * This is determined at compile-time and does not need to checked at
   954→	 * run-time.
   955→	 * 
   956→	 * @return True if write seeking is supported, otherwise false.
   957→	 */
   958→	constexpr static bool can_write_seek() requires writeable<buf_type> {
   959→		return std::is_same_v<seeking, supported>;
   960→	}
   961→
   962→	/**
   963→	 * @brief Performs write seeking within the stream.
   964→	 * 
   965→	 * @param direction Specify whether to seek in a given direction or to absolute seek.
   966→	 * @param offset The offset relative to the seek direction or the absolute value
   967→	 * when using absolute seeking.
   968→	 */
   969→	void write_seek(const stream_seek direction, const offset_type offset)
   970→	requires(seekable<buf_type> && writeable<buf_type>) {
   971→		if(direction == stream_seek::sk_stream_absolute) {
   972→			if(offset >= total_write_) {
   973→				buffer_.write_seek(buffer_seek::sk_forward, offset - total_write_);
   974→			} else {
   975→				buffer_.write_seek(buffer_seek::sk_backward, total_write_ - offset);
   976→			}
   977→
   978→			total_write_ = offset;
   979→		} else {
   980→			buffer_.write_seek(static_cast<buffer_seek>(direction), offset);
   981→		}
   982→	}
   983→
   984→	/**
   985→	 * @brief Returns the size of the underlying buffer.
   986→	 * 
   987→	 * @note The value returned may be higher than the total number of bytes
   988→	 * that can be read from this stream, if a read limit was set during
   989→	 * construction. Use read_max() to determine how many bytes can be
   990→	 * read from this stream.
   991→	 * 
   992→	 * @return The size of the underlying buffer.
   993→	 */
   994→	size_type size() const {
   995→		return buffer_.size();
   996→	}
   997→
   998→	/**
   999→	 * @brief Whether the stream is empty.
  1000→	 * 
  1001→	 * @return Returns true if the stream is empty (has no data to be read).
  1002→	 */
  1003→	[[nodiscard]]
  1004→	bool empty() const {
  1005→		return buffer_.empty();
  1006→	}
  1007→
  1008→	/**
  1009→	 * @return The total number of bytes written to the stream.
  1010→	 */
  1011→	size_type total_write() const requires writeable<buf_type> {
  1012→		return total_write_;
  1013→	}
  1014→
  1015→	/**
  1016→	 * @return Pointer to stream's underlying buffer.
  1017→	 */
  1018→	const buf_type* buffer() const {
  1019→		return &buffer_;
  1020→	}
  1021→
  1022→	/**
  1023→	 * @return Pointer to stream's underlying buffer.
  1024→	 */
  1025→	buf_type* buffer() {
  1026→		return &buffer_;
  1027→	}
  1028→
  1029→	/**
  1030→	 * @return The stream's state.
  1031→	 */
  1032→	stream_state state() const {
  1033→		return state_;
  1034→	}
  1035→
  1036→	/**
  1037→	 * @return The total number of bytes read from the stream.
  1038→	 */
  1039→	size_type total_read() const {
  1040→		return total_read_;
  1041→	}
  1042→
  1043→	/**
  1044→	 * @return If provided to the constructor, the upper limit on how much data
  1045→	 * can be read from this stream before an error is triggers.
  1046→	 */
  1047→	size_type read_limit() const {
  1048→		return read_limit_;
  1049→	}
  1050→
  1051→	/**
  1052→	 * @brief Determine the maximum number of bytes that can be
  1053→	 * safely read from this stream.
  1054→	 * 
  1055→	 * The value returned may be lower than the amount of data
  1056→	 * available in the buffer if a read limit was set during
  1057→	 * the stream's construction.
  1058→	 * 
  1059→	 * @return The number of bytes available for reading.
  1060→	 */
  1061→	size_type read_max() const {
  1062→		if(read_limit_) {
  1063→			assert(total_read_ < read_limit_);
  1064→			return read_limit_ - total_read_;
  1065→		} else {
  1066→			return buffer_.size();
  1067→		}
  1068→	}
  1069→
  1070→	/**
  1071→	 * @brief Determine whether the stream is in a usable state.
  1072→	 * 
  1073→	 * @return true if no errors have occurred.
  1074→	 */
  1075→	bool good() const {
  1076→		return state_ == stream_state::ok;
  1077→	}
  1078→
  1079→	/**
  1080→	 * @brief Resets the stream state back to a good state, allowing
  1081→	 * it to be used for streaming operations again. Has no effect
  1082→	 * if the stream has not errored.
  1083→	 */
  1084→	void clear_state() {
  1085→		state_ = stream_state::ok;
  1086→	}
  1087→
  1088→	operator bool() const {
  1089→		return good();
  1090→	}
  1091→
  1092→	/**
  1093→	 * @brief Set the stream to an error state.
  1094→	 */
  1095→	void set_error_state() {
  1096→		state_ = stream_state::user_defined_err;
  1097→	}
  1098→};
