    19→class buffer_adaptor final : public buffer_read_adaptor<buf_type>,
    20→                             public buffer_write_adaptor<buf_type>,
    21→                             public buffer {
    22→	void conditional_clear() {
    23→		if(buffer_read_adaptor<buf_type>::read_ptr() == buffer_write_adaptor<buf_type>::write_ptr()) {
    24→			clear();
    25→		}
    26→	}
