    89→	 * @brief Copies a number of bytes to the provided buffer but without advancing
    90→	 * the read cursor.
    91→	 * 
    92→	 * @param destination The buffer to copy the data to.
    93→	 * @param length The number of bytes to copy.
    94→	 */
    95→	void copy(void* destination, std::size_t length) const override {
    96→		buffer_read_adaptor<buf_type>::copy(destination, length);
    97→	};
    98→
    99→	/**
   100→	 * @brief Skip over a number of bytes.
   101→	 *
   102→	 * Skips over a number of bytes from the container. This should be used
   103→	 * if the container holds data that you don't care about but don't want
   104→	 * to have to read it to another buffer to access data beyond it.
   105→	 * 
   106→	 * @param length The number of bytes to skip.
