   113→		}
   114→	};
   115→
   116→	/**
   117→	 * @brief Retrieves a reference to the specified index within the container.
   118→	 * 
   119→	 * @param index The index within the container.
   120→	 * 
   121→	 * @return A reference to the value at the specified index.
   122→	 */
   123→	const std::byte& operator[](const std::size_t index) const override { 
   124→		return buffer_read_adaptor<buf_type>::operator[](index); 
   125→	};
   126→
   127→	/**
   128→	 * @brief Retrieves a reference to the specified index within the container.
   129→	 * 
   130→	 * @param index The index within the container.
   131→	 * 
   132→	 * @return A reference to the value at the specified index.
   133→	 */
   134→	std::byte& operator[](const std::size_t index) override {
