#include <hexi/pmc/buffer_read_adaptor.h>
#include <hexi/pmc/buffer_write_adaptor.h>
#include <vector>
#include <cstdint>

std::vector<uint8_t> write_and_read_data(const std::vector<uint8_t>& input_data) {
    // Create a vector buffer for storage
    std::vector<uint8_t> buffer;

    // Create buffer_write_adaptor to write data
    hexi::pmc::buffer_write_adaptor<std::vector<uint8_t>> write_adaptor(buffer);

    // Check available space before writing (for demonstration)
    // free() returns the amount of free space in the buffer
    auto free_space = write_adaptor.free();

    // Write the input data to the buffer
    write_adaptor.write(input_data.data(), input_data.size());

    // Now create buffer_read_adaptor to read it back
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> read_adaptor(buffer);

    // Check the readable size
    auto readable_size = read_adaptor.size();

    // Create output vector and read data back
    std::vector<uint8_t> output_data(readable_size);
    read_adaptor.read(output_data.data(), readable_size);

    return output_data;
}

std::vector<uint8_t> peek_data_without_advancing(const std::vector<uint8_t>& buffer_data, std::size_t peek_size) {
    // Create a mutable copy of the buffer since adaptors require non-const reference
    std::vector<uint8_t> buffer_copy = buffer_data;

    // Create buffer_read_adaptor
    hexi::pmc::buffer_read_adaptor<std::vector<uint8_t>> read_adaptor(buffer_copy);

    // Get pointer to current read position
    auto current_ptr = read_adaptor.read_ptr();

    // Use copy() to peek at data without advancing the read cursor
    std::vector<uint8_t> peeked_data(peek_size);
    read_adaptor.copy(peeked_data.data(), peek_size);

    // Verify that read_ptr() hasn't moved after copy()
    auto ptr_after_copy = read_adaptor.read_ptr();
    // current_ptr == ptr_after_copy (they should be the same)

    // Now actually consume the data using read()
    std::vector<uint8_t> consumed_data(peek_size);
    read_adaptor.read(consumed_data.data(), peek_size);

    // After read(), the read pointer has advanced
    auto ptr_after_read = read_adaptor.read_ptr();
    // ptr_after_read == current_ptr + peek_size

    return peeked_data;
}
```

Here's the complete implementation:

**Key points about the implementation:**

1. **`write_and_read_data` function:**
   - Creates a `std::vector<uint8_t>` buffer for storage
   - Uses `buffer_write_adaptor` to write data with the `write()` method
   - Uses `free()` to check available space (the buffer automatically resizes for vectors)
   - Uses `buffer_read_adaptor` to read the data back
   - Uses `size()` to check how many bytes are available to read
   - Returns the read data

2. **`peek_data_without_advancing` function:**
   - Creates a buffer from the input data
   - Uses `buffer_read_adaptor` to access the data
   - Uses `read_ptr()` to get a pointer to the current read position
   - Uses `copy()` to peek at the data WITHOUT advancing the read cursor
   - Then uses `read()` to actually consume the data, which DOES advance the cursor
   - Returns the peeked data

The implementation demonstrates the key difference between `copy()` (non-destructive peek) and `read()` (consumes data and advances the cursor).

