   154→	/**
   155→	 * @brief Deserialises a string that was previously written with a
   156→	 * fixed-length prefix.
   157→	 * 
   158→	 * @param[out] adaptor std::string to hold the result.
   159→	 * 
   160→	 * @return Reference to the current stream.
   161→	 */
   162→	binary_stream_reader& operator>>(prefixed<std::string> adaptor) {
   163→		std::uint32_t size = 0;
   164→		*this >> endian::le(size);
   165→
   166→		if(state() != stream_state::ok) {
   167→			return *this;
   168→		}
   169→
   170→		STREAM_READ_BOUNDS_ENFORCE(size, *this);
   171→
   172→		adaptor->resize_and_overwrite(size, [&](char* strbuf, std::size_t size) {
   173→			buffer_.read(strbuf, size);
   174→			return size;
   175→		});
   176→
   177→		return *this;
   178→	}
   179→	
   180→	/**
   181→	 * @brief Deserialises a string that was previously written with a
   182→	 * variable-length prefix.
   183→	 * 
   184→	 * @param[out] adaptor std::string to hold the result.
   185→	 * 
   186→	 * @return Reference to the current stream.
   187→	 */
   188→	binary_stream_reader& operator>>(prefixed_varint<std::string> adaptor) {
   189→		const auto size = varint_decode<std::size_t>(*this);
   190→
   191→		// if an error was triggered during decode, we shouldn't reach here
   192→		if(state() != stream_state::ok) {
   193→			std::unreachable();
   194→		}
   195→
   196→		STREAM_READ_BOUNDS_ENFORCE(size, *this);
   197→
   198→		adaptor->resize_and_overwrite(size, [&](char* strbuf, std::size_t size) {
   199→			buffer_.read(strbuf, size);
   200→			return size;
   201→		});
   202→
   203→		return *this;
   204→	}
   205→
   206→	/**
   207→	 * @brief Deserialises a string that was previously written with a
   208→	 * null terminator.
   209→	 * 
   210→	 * @param[out] adaptor std::string to hold the result.
   211→	 * 
   212→	 * @return Reference to the current stream.
   213→	 */
   214→	binary_stream_reader& operator>>(null_terminated<std::string> adaptor) {
   215→		auto pos = buffer_.find_first_of(std::byte{0});
   216→
   217→		if(pos == buffer_.npos) {
   218→			adaptor->clear();
   219→			return *this;
   220→		}
   221→
   222→		STREAM_READ_BOUNDS_ENFORCE(pos + 1, *this); // include null terminator
   223→
   224→		adaptor->resize_and_overwrite(pos, [&](char* strbuf, std::size_t size) {
   225→			buffer_.read(strbuf, pos);
   226→			return size;
   227→		});
   228→
   229→		buffer_.skip(1); // skip null terminator
   230→		return *this;
   231→	}
   232→
   233→	/**
   234→	 * @brief Deserialises a string that was previously written with a
   235→	 * fixed-length prefix.
   236→	 * 
   237→	 * @param[out] data std::string_view to hold the result.
   238→	 * 
   239→	 * @note The string_view's lifetime is tied to that of the underlying
   240→	 * buffer. You should not make any further writes to the buffer
   241→	 * unless you know it will not cause the data to be overwritten (i.e.
   242→	 * buffer adaptor with optimise disabled).
   243→	 * 
   244→	 * @return Reference to the current stream.
   245→	 */
   246→	binary_stream_reader& operator>>(std::string& data) {
   247→		return *this >> prefixed(data);
   248→	}
   249→
   250→	/**
   251→	 * @brief Deserialises an object that provides a deserialise function:
   252→	 * auto& operator>>(auto& stream);
   253→	 * 
   254→	 * @param[out] data The object to be deserialised.
   255→	 * 
   256→	 * @return Reference to the current stream.
   257→	 */
   258→	binary_stream_reader& operator>>(has_shr_override<binary_stream_reader> auto&& data) {
   259→		return *this >> data;
   260→	}
   261→
   262→	/**
   263→	 * @brief Deserialises an arithmetic type with the requested byte order.
   264→	 * 
   265→	 * @param[out] endian_func The arithmetic type wrapped by the adaptor.
   266→	 * 
   267→	 * @return Reference to the current stream.
   268→	 */
   269→	template<std::derived_from<endian::adaptor_tag_t> endian_func>
   270→	binary_stream_reader& operator>>(endian_func adaptor) {
   271→		SAFE_READ(&adaptor.value, sizeof(adaptor.value), *this);
   272→		adaptor.value = adaptor.from();
   273→		return *this;
   274→	}
   275→
   276→	/**
   277→	 * @brief Deserialises a POD type.
   278→	 * 
   279→	 * @tparam T The type of the POD object.
   280→	 * @param[out] data The object to hold the result.
   281→	 * 
   282→	 * @note Will not be used for types with user-defined serialisation
   283→	 * functions.
   284→	 * 
   285→	 * @return Reference to the current stream.
   286→	 */
   287→	template<pod T>
   288→	requires (!has_shr_override<T, binary_stream_reader>)
   289→	binary_stream_reader& operator>>(T& data) {
   290→		SAFE_READ(&data, sizeof(data), *this);
   291→		return *this;
   292→	}
   293→
   294→	/**
   295→	 * @brief Deserialises a POD type.
   296→	 * 
   297→	 * @param[out] data The object to hold the result.
   298→	 * 
   299→	 * @note Will be used for types without user-defined serialisation
   300→	 * functions.
   301→	 * 
   302→	 * @return Reference to the current stream.
   303→	 */
   304→	binary_stream_reader& operator>>(pod auto& data) {
   305→		SAFE_READ(&data, sizeof(data), *this);
   306→		return *this;
   307→	}
   308→
   309→	/**
   310→	 * @brief Deserialises an iterable container that was previously written
   311→	 * with a fixed-length prefix.
   312→	 * 
   313→	 * @tparam T The iterable container type.
   314→	 * @param[out] adaptor The container to hold the result.
   315→	 *  
   316→	 * @return Reference to the current stream.
   317→	 */
   318→	template<is_iterable T>
   319→	binary_stream_reader& operator>>(prefixed<T> adaptor) {
   320→		std::uint32_t count = 0;
   321→		*this >> endian::le(count);
   322→		read_container(adaptor.str, count);
   323→		return *this;
   324→	}
   325→
   326→	/**
   327→	 * @brief Deserialises an iterable container that was previously written
   328→	 * with a variable-length prefix.
   329→	 * 
   330→	 * @tparam T The iterable container type.
   331→	 * @param[out] adaptor The container to hold the result.
   332→	 *  
   333→	 * @return Reference to the current stream.
   334→	 */
   335→	template<is_iterable T>
   336→	binary_stream_reader& operator>>(prefixed_varint<T> adaptor) {
   337→		const auto count = varint_decode<std::size_t>(*this);
   338→		read_container(adaptor.str, count);
   339→		return *this;
   340→	}
   341→
   342→	/**
   343→	 * @brief Reads a string from the stream.
   344→	 * 
   345→	 * @param[out] dest The std::string to hold the result.
   346→	 * 
   347→	 * @param dest The destination string.
   348→	 */
   349→	void get(std::string& dest) {
   350→		*this >> dest;
   351→	}
   352→
   353→	/**
   354→	 * @brief Reads a fixed-length string from the stream.
   355→	 * 
   356→	 * @param[out] dest The std::string to hold the result.
   357→	 * @param count The number of bytes to be read.
   358→	 */
   359→	void get(std::string& dest, std::size_t size) {
   360→		STREAM_READ_BOUNDS_ENFORCE(size, void());
   361→
   362→		dest.resize_and_overwrite(size, [&](char* strbuf, std::size_t len) {
   363→			buffer_.read(strbuf, len);
   364→			return len;
   365→		});
   366→	}
   367→
   368→	/**
   369→	 * @brief Read data from the stream into the provided destination argument.
   370→	 * 
   371→	 * @param[out] dest The destination buffer.
   372→	 * @param count The number of elements to be read into the destination.
   373→	 */
   374→	template<typename T>
   375→	void get(T* dest, std::size_t count) {
   376→		assert(dest);
   377→		const auto read_size = count * sizeof(T);
   378→		SAFE_READ(dest, read_size, void());
   379→	}
   380→
   381→	/**
   382→	 * @brief Read data from the stream to the destination represented by the iterators.
   383→	 * 
   384→	 * @param[out] begin The beginning iterator.
   385→	 * @param end The end iterator.
   386→	 */
   387→	template<typename It>
   388→	void get(It begin, const It end) {
   389→		for(; begin != end; ++begin) {
   390→			*this >> *begin;
   391→		}
   392→	}
   393→
   394→	/**
   395→	 * @brief Read data from the stream into the provided destination argument.
   396→	 * 
   397→	 * @param[out] dest A contiguous range into which the data should be read.
   398→	 */
   399→	template<std::ranges::contiguous_range range>
   400→	void get(range& dest) {
   401→		const auto read_size = dest.size() * sizeof(typename range::value_type);
   402→		SAFE_READ(dest.data(), read_size, void());
   403→	}
   404→
   405→	/**
   406→	 * @brief Read an arithmetic type from the stream, allowing for endian
   407→	 * conversion.
   408→	 * 
   409→	 * @return The arithmetic value.
   410→	 */
   411→	template<arithmetic T>
   412→	T get() {
   413→		T t{};
   414→		SAFE_READ(&t, sizeof(T), t);
   415→		return t;
   416→	}
   417→
   418→	/**
   419→	 * @brief Read an arithmetic type from the stream.
   420→	 * 
   421→	 * @param[out] dest The variable to hold the result.
   422→	 */
   423→	void get(arithmetic auto& dest) {
   424→		SAFE_READ(&dest, sizeof(dest), void());
   425→	}
   426→
   427→	/**
   428→	 * @brief Read an arithmetic type from the stream, allowing for endian
   429→	 * conversion.
   430→	 * 
   431→	 * @param[out] adaptor The destination for the read value.
   432→	 */
   433→	template<std::derived_from<endian::adaptor_tag_t> endian_func>
   434→	void get(endian_func& adaptor) {
   435→		SAFE_READ(&adaptor.value, sizeof(adaptor.value), void());
   436→		adaptor.value = adaptor.from();
   437→	}
   438→
   439→	/**
   440→	 * @brief Read an arithmetic type from the stream, allowing for endian
   441→	 * conversion.
   442→	 * 
   443→	 * @return The arithmetic value.
   444→	 */
   445→	template<arithmetic T, endian::conversion conversion>
   446→	T get() {
   447→		T t{};
   448→		SAFE_READ(&t, sizeof(T), t);
   449→		return endian::convert<conversion>(t);
   450→	}
   451→
   452→	/**  Misc functions **/ 
   453→
   454→	/**
   455→	 * @brief Skip over a number of bytes.
   456→	 *
   457→	 * Skips over a number of bytes from the stream. This should be used
   458→	 * if the stream holds data that you don't care about but don't want
   459→	 * to have to read it to another buffer to access data beyond it.
   460→	 * 
   461→	 * @param length The number of bytes to skip.
   462→	 */
   463→	void skip(std::size_t length) {
   464→		STREAM_READ_BOUNDS_ENFORCE(length, void());
   465→		buffer_.skip(length);
   466→	}
   467→
   468→	/**
   469→	 * @return The total number of bytes read from the stream.
   470→	 */
   471→	std::size_t total_read() const {
   472→		return total_read_;
   473→	}
   474→
   475→	/**
   476→	 * @return If provided to the constructor, the upper limit on how much data
   477→	 * can be read from this stream before an error is triggers.
   478→	 */
   479→	std::size_t read_limit() const {
   480→		return read_limit_;
   481→	}
   482→
   483→	/**
   484→	 * @brief Determine the maximum number of bytes that can be
   485→	 * safely read from this stream.
   486→	 * 
   487→	 * The value returned may be lower than the amount of data
   488→	 * available in the buffer if a read limit was set during
   489→	 * the stream's construction.
   490→	 * 
   491→	 * @return The number of bytes available for reading.
   492→	 */
   493→	std::size_t read_max() const {
   494→		if(read_limit_) {
   495→			assert(total_read_ < read_limit_);
   496→			return read_limit_ - total_read_;
   497→		} else {
   498→			return buffer_.size();
   499→		}
   500→	}
   501→
   502→	/** 
   503→	 * @brief Get a pointer to the buffer read interface.
   504→	 *
   505→	 * @return Pointer to the buffer read interface. 
   506→	 */
   507→	buffer_read* buffer() {
   508→		return &buffer_;
   509→	}
   510→
   511→	/** 
   512→	 * @brief Get a pointer to the buffer read interface.
   513→	 *
   514→	 * @return Pointer to the buffer read interface. 
   515→	 */
   516→	const buffer_read* buffer() const {
   517→		return &buffer_;
   518→	}
   519→};
