   165→public:
   166→	explicit binary_stream(buf_type& source, size_type read_limit = 0)
   167→		: buffer_(source),
   168→		  read_limit_(read_limit) {};
   169→
   170→	explicit binary_stream(buf_type& source, exceptions)
   171→		: binary_stream(source, 0) {}
   172→
   173→	explicit binary_stream(buf_type& source, endianness)
   174→		: binary_stream(source, 0) {}
   175→
   176→	explicit binary_stream(buf_type& source, exceptions, endianness)
   177→		: binary_stream(source, 0) {}
   178→
   179→	explicit binary_stream(buf_type& source, size_type read_limit, exceptions)
   180→		: binary_stream(source, read_limit) {}
   181→
   182→	explicit binary_stream(buf_type& source, size_type read_limit, endianness)
   183→		: binary_stream(source, read_limit) {}
   184→
   185→	explicit binary_stream(buf_type& source, size_type read_limit, exceptions, endianness)
   186→		: binary_stream(source, read_limit) {}
   187→
   188→	binary_stream(binary_stream&& rhs) noexcept
   189→		: buffer_(rhs.buffer_), 
   190→		  total_write_(rhs.total_write_),
   191→		  total_read_(rhs.total_read_),
   192→		  state_(rhs.state_),
   193→		  read_limit_(rhs.read_limit_) {
   194→		rhs.total_read_ = static_cast<size_type>(-1);
   195→		rhs.state_ = stream_state::invalid_stream;
   196→	}
   197→
   198→	binary_stream& operator=(binary_stream&&) = delete;
   199→	binary_stream& operator=(binary_stream&) = delete;
   200→	binary_stream(binary_stream&) = delete;
   201→
   202→	/*** Write ***/
   203→
   204→	/**
   205→	 * @brief Serialises an object that provides a serialise function:
   206→	 * void serialise(auto& stream);
   207→	 * 
   208→	 * @param object The object to be serialised.
   209→	 */
   210→	void serialise(auto&& object) requires writeable<buf_type> {
   211→		stream_write_adaptor adaptor(*this);
   212→		object.serialise(adaptor);
   213→	}
   214→
   215→	/**
   216→	 * @brief Serialises an object that provides a serialise function:
   217→	 * void serialise(auto& stream);
   218→	 * 
   219→	 * @param data The object to be serialised.
   220→	 * 
   221→	 * @return Reference to the current stream.
   222→	 */
   223→	template<typename T>
   224→	requires has_serialise<T, binary_stream>
   225→	binary_stream& operator<<(T& data) requires writeable<buf_type> {
   226→		serialise(data);
   227→		return *this;
   228→	}
   229→
   230→	/**
   231→	 * @brief Serialises an object that provides a serialise function:
   232→	 * auto& operator<<(auto& stream);
   233→	 * 
   234→	 * @param data The object to be serialised.
   235→	 * 
   236→	 * @return Reference to the current stream.
   237→	 */
   238→	binary_stream& operator<<(const has_shl_override<binary_stream> auto& data)
   239→	requires writeable<buf_type> {
   240→		return *this << data;
   241→	}
   242→
   243→	/**
   244→	 * @brief Serialises an arithmetic type with the requested byte order.
   245→	 * 
   246→	 * @param adaptor An endian adaptor.
   247→	 * 
   248→	 * @return Reference to the current stream.
   249→	 */
   250→	template<std::derived_from<endian::adaptor_tag_t> endian_func>
   251→	binary_stream& operator<<(endian_func adaptor) requires writeable<buf_type> {
   252→		const auto converted = adaptor.to();
   253→		write(&converted, sizeof(converted));
   254→		return *this;
   255→	}
   256→
   257→	/**
   258→	 * @brief Serialises an arithmetic type with the default byte order.
   259→	 * 
   260→	 * @param data Reference to the type to be serialised.
   261→	 * 
   262→	 * @return Reference to the current stream.
   263→	 */
   264→	binary_stream& operator<<(const arithmetic auto& data) requires writeable<buf_type> {
   265→		const auto converted = endian::storage_in(data, byte_order);
   266→		write(&converted, sizeof(converted));
   267→		return *this;
   268→	}
   269→
   270→	/**
   271→	 * @brief Serialises a POD type.
   272→	 * 
   273→	 * @tparam T The type of the POD object.
   274→	 * @param data Reference to the object to be serialised.
   275→	 * 
   276→	 * @note Will not be used for types with user-defined serialisation
   277→	 * functions.
   278→	 * 
   279→	 * @return Reference to the current stream.
   280→	 */
   281→	template<pod T>
   282→	requires (!has_shl_override<T, binary_stream> && !arithmetic<T>)
   283→	binary_stream& operator<<(const T& data) requires writeable<buf_type> {
   284→		write(&data, sizeof(T));
   285→		return *this;
   286→	}
   287→
   288→	/**
   289→	 * @brief Serialises a string or string_view with a fixed-length prefix
   290→	 * 
   291→	 * @tparam T The string type.
   292→	 * @param adaptor prefixed adaptor that will instruct the stream to write a length
   293→	 * prefix before serialising the string.
   294→	 * 
   295→	 * @return Reference to the current stream.
   296→	 */
   297→	template<typename T>
   298→	requires std::is_same_v<std::decay_t<T>, std::string_view>
   299→	binary_stream& operator<<(null_terminated<T> adaptor) requires writeable<buf_type> {
   300→		assert(adaptor->find_first_of('\0') == adaptor->npos);
   301→		write(adaptor->data(), adaptor->size());
   302→		write('\0');
   303→		return *this;
   304→	}
   305→
   306→	/**
   307→	 * @brief Serialises a string_view as a null terminated string.
   308→	 * 
   309→	 * @tparam T The string type.
   310→	 * @param adaptor null_terminated adaptor that will instruct the stream to write
   311→	 * a null terminated string with no prefix.
   312→	 * 
   313→	 * @return Reference to the current stream.
   314→	 */
   315→	template<typename T>
   316→	requires std::is_same_v<std::decay_t<T>, std::string>
   317→	binary_stream& operator<<(null_terminated<T> adaptor) requires writeable<buf_type> {
   318→		assert(adaptor->find_first_of('\0') == adaptor->npos);
   319→		write(adaptor->data(), adaptor->size() + 1); // yes, the standard allows this
   320→		return *this;
   321→	}
   322→
   323→	/**
