#include <hexi/binary_stream.h>
#include <hexi/dynamic_buffer.h>
#include <vector>
#include <cstdint>

struct TypedData {
    uint32_t id;
    int16_t value;
    double ratio;
};

std::vector<uint8_t> write_typed_data(const TypedData& data) {
    // Create a dynamic buffer backed by a vector
    hexi::dynamic_buffer<std::vector<uint8_t>> buffer;

    // Create a binary stream with the buffer
    hexi::binary_stream stream(buffer);

    // Write each field using the << operator
    stream << data.id;
    stream << data.value;
    stream << data.ratio;

    // Return the underlying vector data
    return buffer.vector();
}

TypedData read_typed_data(const std::vector<uint8_t>& buffer) {
    // Create a dynamic buffer from the input vector
    hexi::dynamic_buffer<std::vector<uint8_t>> buf(buffer);

    // Create a binary stream for reading
    hexi::binary_stream stream(buf);

    // Read each field in the same order they were written
    TypedData data;
    stream >> data.id;
    stream >> data.value;
    stream >> data.ratio;

    return data;
}
```

