    23→template<byte_type storage_type, std::size_t buf_size>
    24→class static_buffer final {
    25→	std::array<storage_type, buf_size> buffer_ = {};
    26→	std::size_t read_ = 0;
    27→	std::size_t write_ = 0;
    28→
    29→public:
    30→	using size_type       = typename decltype(buffer_)::size_type;
    31→	using offset_type     = size_type;
    32→	using value_type      = storage_type;
    33→	using contiguous      = is_contiguous;
    34→	using seeking         = supported;
    35→
    36→	static constexpr auto npos { static_cast<size_type>(-1) };
    37→	
    38→	static_buffer() = default;
    39→
    40→	template<typename... T> 
    41→	static_buffer(T&&... vals) : buffer_{ std::forward<T>(vals)... } {
    42→		write_ = sizeof... (vals);
    43→	}
    44→
    45→	static_buffer(static_buffer&& rhs) = default;
    46→	static_buffer& operator=(static_buffer&&) = default;
    47→	static_buffer& operator=(const static_buffer&) = default;
    48→	static_buffer(const static_buffer&) = default;
    49→
    50→	/**
    51→	 * @brief Reads a number of bytes to the provided buffer.
    52→	 * 
    53→	 * @param destination The buffer to copy the data to.
    54→	 */
    55→	template<typename T>
    56→	void read(T* destination) {
    57→		read(destination, sizeof(T));
    58→	}
    59→
    60→	/**
    61→	 * @brief Reads a number of bytes to the provided buffer.
    62→	 * 
    63→	 * @param destination The buffer to copy the data to.
    64→	 * @param length The number of bytes to read into the buffer.
    65→	 */
    66→	void read(void* destination, size_type length) {
    67→		copy(destination, length);
    68→		read_ += length;
    69→
    70→		if(read_ == write_) {
    71→			read_ = write_ = 0;
    72→		}
    73→	}
    74→
    75→	/**
    76→	 * @brief Copies a number of bytes to the provided buffer but without advancing
    77→	 * the read cursor.
    78→	 * 
    79→	 * @param destination The buffer to copy the data to.
    80→	 */
    81→	template<typename T>
    82→	void copy(T* destination) const {
    83→		copy(destination, sizeof(T));
    84→	}
    85→
    86→	/**
    87→	 * @brief Copies a number of bytes to the provided buffer but without advancing
    88→	 * the read cursor.
    89→	 * 
    90→	 * @note The destination buffer address must not belong to the static_buffer.
    91→	 * 
    92→	 * @param destination The buffer to copy the data to.
    93→	 * @param length The number of bytes to copy.
    94→	 */
    95→	void copy(void* destination, size_type length) const {
    96→		assert(!region_overlap(buffer_.data(), buffer_.size(), destination, length));
    97→
    98→		if(length > size()) {
    99→			HEXI_THROW(buffer_underrun(length, read_, size()));
   100→		}
   101→
   102→		std::memcpy(destination, read_ptr(), length);
   103→	}
   104→
   105→	/**
   106→	 * @brief Attempts to locate the provided value within the container.
   107→	 * 
   108→	 * @param value The value to locate.
   109→	 * 
   110→	 * @return The position of value or npos if not found.
   111→	 */
   112→	size_type find_first_of(value_type val) const noexcept {
   113→		const auto data = read_ptr();
   114→
   115→		for(size_type i = 0, j = size(); i < j; ++i) {
   116→			if(data[i] == val) {
   117→				return i;
   118→			}
   119→		}
   120→
   121→		return npos;
   122→	}
   123→
   124→	/**
   125→	 * @brief Skip over a number of bytes.
   126→	 * 
   127→	 * Skips over a number of bytes from the container. This should be used
   128→	 * if the container holds data that you don't care about but don't want
   129→	 * to have to read it to another buffer to access data beyond it.
   130→	 * 
   131→	 * @param length The number of bytes to skip.
   132→	 */
   133→	void skip(const size_type length) {
   134→		read_ += length;
   135→
   136→		if(read_ == write_) {
   137→			read_ = write_ = 0;
   138→		}
   139→	}
   140→
   141→	/**
   142→	 * @brief Advances the write cursor.
   143→	 * 
   144→	 * @param size The number of bytes by which to advance the write cursor.
   145→	 */
   146→	void advance_write(size_type bytes) {
   147→		assert(free() >= bytes);
   148→		write_ += bytes;
   149→	}
   150→
   151→	/**
   152→	 * @brief Resizes the buffer.
   153→	 * 
   154→	 * @param size The new size of the buffer.
   155→	 * 
   156→	 */
   157→	void resize(size_type size) {
   158→		if(size > buffer_.size()) {
   159→			HEXI_THROW(exception("attempted to resize static_buffer to larger than capacity"));
   160→		}
   161→
   162→		write_ = size;
   163→	}
   164→
   165→	/**
   166→	 * @brief Clears the container.
   167→	 */
   168→	void clear() {
   169→		read_ = write_ = 0;
   170→	}
   171→
   172→	/**
   173→	 * @brief Moves any unread data to the front of the buffer, freeing space at the end.
   174→	 * If a move is performed, pointers obtained from read/write_ptr() will be invalidated.
   175→	 * 
   176→	 * If the buffer contains no data available for reading, this function will have no effect.
   177→	 * 
   178→	 * @return True if additional space was made available.
   179→	 */
   180→	bool defragment() {
   181→		if(read_ == 0) {
   182→			return false;
   183→		}
   184→
   185→		write_ = size();
   186→		std::memmove(buffer_.data(), read_ptr(), write_);
   187→		read_ = 0;
   188→		return true;
   189→	}
   190→
   191→	/**
   192→	 * @brief Retrieves a reference to the specified index within the container.
   193→	 * 
   194→	 * @param index The index within the container.
   195→	 * 
   196→	 * @return A reference to the value at the specified index.
   197→	 */
   198→	value_type& operator[](const size_type index) {
   199→		return read_ptr()[index];
   200→	}
   201→
   202→	/**
   203→	 * @brief Retrieves a reference to the specified index within the container.
   204→	 * 
   205→	 * @param index The index within the container.
   206→	 * 
   207→	 * @return A reference to the value at the specified index.
   208→	 */
   209→	const value_type& operator[](const size_type index) const {
   210→		return read_ptr()[index];
   211→	}
   212→
   213→	/**
   214→	 * @brief Whether the container is empty.
   215→	 * 
   216→	 * @return Returns true if the container is empty (has no data to be read).
   217→	 */
   218→	[[nodiscard]]
   219→	bool empty() const {
   220→		return write_ == read_;
   221→	}
   222→
   223→	/**
   224→	 * @return Whether the container is full and cannot be further written to.
   225→	 */
   226→	bool full() const {
   227→		return write_ == capacity();
   228→	}
