    // Write data in multiple separate calls to write()
    for (const auto& chunk : chunks) {
        // Use free() to check available space before each write
        if (buffer.free() < chunk.size()) {
            // Not enough space for this chunk
            break;
        }

        // Write the chunk to the buffer
        buffer.write(chunk.data(), chunk.size());
    }

    // Return the total size written (which is the current buffer size)
    return buffer.size();
}

