    // Create a static buffer and write the initial data to it
    hexi::static_buffer<uint8_t, 4096> hexi_buffer;
    hexi_buffer.write(buffer.data(), buffer.size());

    std::vector<uint8_t> result;

    // Read until buffer is empty
    while (!hexi_buffer.empty()) {
        // Use size() to check remaining data after each read
        std::size_t remaining = hexi_buffer.size();

        // Determine how much to read in this iteration
        std::size_t to_read = (remaining < chunk_size) ? remaining : chunk_size;

        // Allocate temporary storage for this chunk
        std::vector<uint8_t> temp(to_read);

        // Read the chunk
        hexi_buffer.read(temp.data(), to_read);

        // Append to result
        result.insert(result.end(), temp.begin(), temp.end());
    }

    return result;
}
