#include <hexi.h>
#include <vector>
#include <span>
#include <cstdint>

struct ProtocolPacket {
    uint32_t message_id;
    std::vector<uint16_t> data_values;
    uint32_t checksum;
};

std::vector<uint8_t> serialize_protocol_packet(const ProtocolPacket& packet) {
    // Create a buffer to hold the serialized data
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer);
    hexi::binary_stream stream(adaptor);

    // Convert message_id from native to big-endian and write
    const auto message_id_be = hexi::endian::native_to_big(packet.message_id);
    stream.put(&message_id_be, 1);

    // Write the count of data_values (converted to big-endian)
    const auto count_be = hexi::endian::native_to_big(static_cast<uint32_t>(packet.data_values.size()));
    stream.put(&count_be, 1);

    // Convert each element in data_values from native to big-endian and write
    for (const auto& value : packet.data_values) {
        const auto value_be = hexi::endian::native_to_big(value);
        stream.put(&value_be, 1);
    }

    // Convert checksum from native to big-endian and write
    const auto checksum_be = hexi::endian::native_to_big(packet.checksum);
    stream.put(&checksum_be, 1);

    return buffer;
}

ProtocolPacket deserialize_protocol_packet(const std::span<const uint8_t> buffer) {
    ProtocolPacket packet;

    // Create a const buffer for reading
    hexi::const_buffer_adaptor adaptor(buffer.data(), buffer.size());
    hexi::binary_stream stream(adaptor);

    // Read message_id and convert from big-endian to native
    uint32_t message_id_be = 0;
    stream.get(&message_id_be, 1);
    packet.message_id = hexi::endian::big_to_native(message_id_be);

    // Read count of data_values and convert from big-endian to native
    uint32_t count_be = 0;
    stream.get(&count_be, 1);
    const uint32_t count = hexi::endian::big_to_native(count_be);

    // Reserve space and read data_values, converting each from big-endian to native
    packet.data_values.reserve(count);
    for (uint32_t i = 0; i < count; ++i) {
        uint16_t value_be = 0;
        stream.get(&value_be, 1);
        packet.data_values.push_back(hexi::endian::big_to_native(value_be));
    }

    // Read checksum and convert from big-endian to native
    uint32_t checksum_be = 0;
    stream.get(&checksum_be, 1);
    packet.checksum = hexi::endian::big_to_native(checksum_be);

    return packet;
}

struct ProtocolHeader {
    uint32_t message_id;
};

ProtocolHeader extract_protocol_header(const std::span<const uint8_t> buffer) {
    ProtocolHeader header;

    // Create a const buffer for reading
    hexi::const_buffer_adaptor adaptor(buffer.data(), buffer.size());
    hexi::binary_stream stream(adaptor);

    // Use span to get a zero-copy view of the first 4 bytes (message_id)
    auto message_id_span = stream.span<uint32_t>(1);

    // Convert the message_id from big-endian to native
    header.message_id = hexi::endian::big_to_native(message_id_span[0]);

    // No need to skip since span() already advanced the stream position

    return header;
}

int main() {
    // Example usage: Create a protocol packet
    ProtocolPacket packet_in {
        .message_id = 0x12345678,
        .data_values = {100, 200, 300, 400, 500},
        .checksum = 0xABCDEF01
    };

    // Serialize the packet to big-endian format
    std::vector<uint8_t> serialized = serialize_protocol_packet(packet_in);

    // Deserialize the packet back
    ProtocolPacket packet_out = deserialize_protocol_packet(serialized);

    // Verify the round-trip
    bool success = (packet_in.message_id == packet_out.message_id) &&
                   (packet_in.data_values == packet_out.data_values) &&
                   (packet_in.checksum == packet_out.checksum);

    if (success) {
        // Extract only the header
        ProtocolHeader header = extract_protocol_header(serialized);

        // Verify header extraction
        success = (header.message_id == packet_in.message_id);
    }

    return success ? 0 : 1;
}

