struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    // Serialization method (const version for writing)
    void serialise(auto& adaptor) const {
        // Write sensor_id directly (no endianness conversion needed for this field)
        adaptor.write(&sensor_id, sizeof(sensor_id));

        // Convert each temperature from native to little-endian using conditional_reverse
        for (const auto& temp : temperatures) {
            auto converted = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.write(&converted, sizeof(converted));
        }

        // Convert pressure from native to little-endian using conditional_reverse
        auto converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.write(&converted_pressure, sizeof(converted_pressure));
    }

    // Deserialization method (non-const version for reading)
    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor.read(&sensor_id, sizeof(sensor_id));

        // Read each temperature and convert from little-endian to native using little_to_native_inplace
        for (auto& temp : temperatures) {
            adaptor.read(&temp, sizeof(temp));
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native using little_to_native_inplace
        adaptor.read(&pressure, sizeof(pressure));
        hexi::endian::little_to_native_inplace(pressure);
    }
};

std::vector<uint8_t> serialize_measurement_data(const MeasurementData& data) {
    std::vector<uint8_t> buffer;
    hexi::buffer_adaptor adaptor(buffer, hexi::init_empty);
    hexi::binary_stream stream(adaptor);

    // Use the stream's serialise method to serialize the entire structure
    stream.serialise(data);

    return buffer;
}

